class Solution {
public:
    TreeNode* canMerge(vector<TreeNode*>& trees) {
        unordered_map<int, TreeNode*> rootMap;
        unordered_set<int> leaves;
        for (auto t : trees) {
            rootMap[t->val] = t;
            if (t->left) leaves.insert(t->left->val);
            if (t->right) leaves.insert(t->right->val);
        }
        TreeNode* root = nullptr;
        for (auto t : trees) {
            if (!leaves.count(t->val)) {
                if (root) return nullptr;
                root = t;
            }
        }
        if (!root) return nullptr;
        rootMap.erase(root->val);

        auto validate = [&](auto& self, TreeNode* node, long long low, long long high) -> bool {
            if (!node) return true;
            if (node->val <= low || node->val >= high) return false;
            if (!node->left && !node->right && rootMap.count(node->val)) {
                TreeNode* sub = rootMap[node->val];
                rootMap.erase(node->val);
                node->left = sub->left;
                node->right = sub->right;
            }
            return self(self, node->left, low, node->val) && self(self, node->right, node->val, high);
        };

        if (validate(validate, root, LLONG_MIN, LLONG_MAX) && rootMap.empty()) return root;
        return nullptr;
    }
};

class Solution {
    public TreeNode canMerge(java.util.List<TreeNode> trees) {
        java.util.Map<Integer, TreeNode> rootMap = new java.util.HashMap<>();
        java.util.Set<Integer> leaves = new java.util.HashSet<>();
        for (TreeNode t : trees) {
            rootMap.put(t.val, t);
            if (t.left != null) leaves.add(t.left.val);
            if (t.right != null) leaves.add(t.right.val);
        }
        TreeNode root = null;
        for (TreeNode t : trees) {
            if (!leaves.contains(t.val)) {
                if (root != null) return null;
                root = t;
            }
        }
        if (root == null) return null;
        rootMap.remove(root.val);

        if (validate(root, Long.MIN_VALUE, Long.MAX_VALUE, rootMap) && rootMap.isEmpty()) return root;
        return null;
    }

    private boolean validate(TreeNode node, long low, long high, java.util.Map<Integer, TreeNode> rootMap) {
        if (node == null) return true;
        if (node.val <= low || node.val >= high) return false;
        if (node.left == null && node.right == null && rootMap.containsKey(node.val)) {
            TreeNode sub = rootMap.remove(node.val);
            node.left = sub.left;
            node.right = sub.right;
        }
        return validate(node.left, low, node.val, rootMap) && validate(node.right, node.val, high, rootMap);
    }
}

var canMerge = function(trees) {
  const rootMap = new Map();
  const leaves = new Set();
  for (const t of trees) {
    rootMap.set(t.val, t);
    if (t.left) leaves.add(t.left.val);
    if (t.right) leaves.add(t.right.val);
  }
  let root = null;
  for (const t of trees) {
    if (!leaves.has(t.val)) {
      if (root) return null;
      root = t;
    }
  }
  if (!root) return null;
  rootMap.delete(root.val);

  const validate = (node, low, high) => {
    if (!node) return true;
    if (node.val <= low || node.val >= high) return false;
    if (!node.left && !node.right && rootMap.has(node.val)) {
      const sub = rootMap.get(node.val);
      rootMap.delete(node.val);
      node.left = sub.left;
      node.right = sub.right;
    }
    return validate(node.left, low, node.val) && validate(node.right, node.val, high);
  };

  if (validate(root, -Infinity, Infinity) && rootMap.size === 0) return root;
  return null;
};
